add_action( 'woocommerce_product_query', 'perfectpixel_shop_only_categories' );

function perfectpixel_shop_only_categories( $q ) {
	$ids = wp_parse_id_list( '{{shop_only_category_ids}}' );
	if ( ! $ids || ! is_shop() || is_search() ) {
		return;
	}
	$tax_query   = (array) $q->get( 'tax_query' );
	$tax_query[] = array(
		'taxonomy' => 'product_cat',
		'field'    => 'term_id',
		'terms'    => $ids,
		'operator' => 'IN',
	);
	$q->set( 'tax_query', $tax_query );
}
